/**
 * Runtime validation for Pina's PinaPod wire types.
 *
 * This file is generated by `pina codama generate`. The stock Codama codecs
 * intentionally permit truncation and permissive decoding, whereas Pina's
 * on-chain PinaPod views reject those non-canonical representations.
 */

import {
	addDecoderSizePrefix,
	createDecoder,
	type Decoder,
	type Encoder,
	fixDecoderSize,
	type FixedSizeDecoder,
	type FixedSizeEncoder,
	fixEncoderSize,
	getBytesDecoder,
	getU8Decoder,
	transformDecoder,
	transformEncoder,
} from "@solana/kit";

type Integer = bigint | number;
type PinaPodCollection = { readonly length: number };

function assertPinaPodString(value: string, capacity: number): void {
	const bytes = new TextEncoder().encode(value);
	if (bytes.length > capacity) {
		throw new RangeError(
			`PinaPod string needs ${bytes.length} UTF-8 bytes but its capacity is ${capacity}`,
		);
	}
	if (new TextDecoder("utf-8", { fatal: true }).decode(bytes) !== value) {
		throw new TypeError(
			"PinaPod strings must contain valid Unicode scalar values",
		);
	}
}

/** Rejects an oversized collection before its item encoder runs. */
export function getPinaPodBoundedArrayEncoder<TFrom extends PinaPodCollection>(
	encoder: Encoder<TFrom>,
	capacity: number,
): Encoder<TFrom> {
	return transformEncoder(encoder, (value) => {
		if (value.length > capacity) {
			throw new RangeError(
				`PinaPod collection has ${value.length} items but its capacity is ${capacity}`,
			);
		}
		return value;
	});
}

/** Rejects a decoded collection that exceeds its schema capacity. */
export function getPinaPodBoundedArrayDecoder<
	TTo extends PinaPodCollection,
	TCount extends Integer,
>(
	decoder: Decoder<TTo>,
	countDecoder: Decoder<TCount>,
	capacity: number,
): Decoder<TTo> {
	return createDecoder({
		...decoder,
		read: (bytes, offset) => {
			// Security: Codama's array decoder skips its size decoder at end-of-input.
			// Read the shared header count first so an empty tail cannot hide a nonzero count.
			countDecoder.read(bytes, offset);
			const [value, newOffset] = decoder.read(bytes, offset);
			if (value.length > capacity) {
				throw new RangeError(
					`PinaPod collection has ${value.length} items but its capacity is ${capacity}`,
				);
			}

			return [value, newOffset];
		},
	});
}

/** Rejects an oversized count before the array decoder allocates or reads items. */
export function getPinaPodBoundedCountDecoder<TDecoded extends Integer>(
	decoder: Decoder<TDecoded>,
	capacity: number,
): Decoder<TDecoded> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) > BigInt(capacity)) {
			throw new RangeError(
				`PinaPod collection count ${value} exceeds its capacity ${capacity}`,
			);
		}
		return value;
	});
}

/** Enforces a string's UTF-8 byte capacity before its encoder runs. */
export function getPinaPodBoundedStringEncoder(
	encoder: Encoder<string>,
	capacity: number,
): Encoder<string> {
	return transformEncoder(encoder, (value) => {
		assertPinaPodString(value, capacity);
		return value;
	});
}

/** Defensively rechecks a decoded string's UTF-8 byte capacity. */
export function getPinaPodBoundedStringDecoder(
	decoder: Decoder<string>,
	capacity: number,
): Decoder<string> {
	return transformDecoder(decoder, (value) => {
		assertPinaPodString(value, capacity);
		return value;
	});
}

/** Decodes variable-size UTF-8 strictly instead of replacing malformed input. */
export function getPinaPodUtf8Decoder(): Decoder<string> {
	return transformDecoder(
		getBytesDecoder(),
		(value) => new TextDecoder("utf-8", { fatal: true }).decode(value),
	);
}

/** Pads valid values but rejects values that would otherwise be truncated. */
export function fixPinaPodEncoderSize<TFrom, TSize extends number>(
	encoder: Encoder<TFrom>,
	fixedBytes: TSize,
): FixedSizeEncoder<TFrom, TSize> {
	const checkedEncoder = transformEncoder(encoder, (value: TFrom) => {
		const encodedSize = "fixedSize" in encoder
			? encoder.fixedSize
			: encoder.getSizeFromValue(value);
		if (encodedSize > fixedBytes) {
			throw new RangeError(
				`PinaPod value needs ${encodedSize} bytes but its capacity is ${fixedBytes}`,
			);
		}
		return value;
	});

	return fixEncoderSize(checkedEncoder, fixedBytes);
}

/** Decodes UTF-8 strictly and preserves embedded NUL characters. */
export function getPinaPodStringDecoder<TSize extends number>(
	prefix: FixedSizeDecoder<bigint> | FixedSizeDecoder<number>,
	fixedBytes: TSize,
): FixedSizeDecoder<string, TSize> {
	const bytes = addDecoderSizePrefix(getBytesDecoder(), prefix);
	return transformDecoder(
		fixDecoderSize(bytes, fixedBytes),
		(value) => new TextDecoder("utf-8", { fatal: true }).decode(value),
	);
}

/** Accepts only PinaPod's canonical boolean encodings. */
export function getPinaPodBooleanDecoder(): FixedSizeDecoder<boolean, 1> {
	return transformDecoder(getU8Decoder(), (value) => {
		if (value !== 0 && value !== 1) {
			throw new RangeError(`invalid PinaPod boolean: ${value}`);
		}
		return value === 1;
	});
}

/** Accepts only PinaPod's `None` and `Some` option tags. */
export function getPinaPodOptionTagDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== 0n && BigInt(value) !== 1n) {
			throw new RangeError(`invalid PinaPod option tag: ${value}`);
		}
		return value;
	});
}

/** Rejects data for a different account or instruction before decoding it. */
export function getPinaPodDiscriminatorDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	expected: Integer,
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== BigInt(expected)) {
			throw new RangeError(
				`invalid discriminator: expected ${expected}, received ${value}`,
			);
		}
		return value;
	});
}

/** Rejects account or instruction data from another migration version. */
export function getPinaPodMigrationVersionDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	expected: Integer,
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== BigInt(expected)) {
			const hint = BigInt(value) < BigInt(expected)
				? "the data predates this client; migrate it by sending a transaction to the program, or decode it with a client generated from an older IDL"
				: "the data was written by a newer program; upgrade this client";
			throw new RangeError(
				`stale migration version: expected ${expected}, received ${value} (${hint})`,
			);
		}
		return value;
	});
}

/** Rejects numeric enum representations not declared by the native schema. */
export function getPinaPodEnumDecoder<
	TValue extends number,
	TSize extends number,
>(
	decoder: FixedSizeDecoder<TValue, TSize>,
	validValues: readonly TValue[],
): FixedSizeDecoder<TValue, TSize> {
	return transformDecoder(decoder, (value) => {
		if (!validValues.includes(value)) {
			throw new RangeError(`invalid PinaPod enum discriminant: ${value}`);
		}
		return value;
	});
}
